const referralFold=s=>String(s||'').normalize('NFKC').trim().replace(/\s+/g,' ').toLocaleLowerCase();
function referralLead(l){return db.config?.masters?.sources?.find(s=>s.name===l.source)?.kind==='referral'||leadSourceKind(l.source)==='referral'}
