function referralOptions(){const all=new Map();for(const l of visible(db.leads).filter(referralLead)){const g=referralGiver(l),prior=all.get(g.key);const organization=prior&&prior.organization!==g.organization?'Beberapa cabang / organisasi':g.organization;all.set(g.key,{...g,organization,label:g.name+' · '+g.type+(organization?' · '+organization:''),count:(prior?.count||0)+1})}return [...all.values()].sort((a,b)=>a.label.localeCompare(b.label))}
function referralFilter(label,name,items,value,action){return '<label class="ref-filter"><span>'+E(label)+'</span><select aria-label="'+E(label)+'" name="'+name+'" onchange="'+action+'"><option value="">Semua</option>'+items.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return '<option value="'+E(v)+'" '+(v===value?'selected':'')+'>'+E(t)+'</option>'}).join('')+'</select></label>'}
function referralSetLead(value,type=false){if(type)referralLeadType=value;else referralLeadFilter=value;if(value)leadChip='Semua';listPage=1;renderContent()}
const referralPriorList=getList;
getList=function(name=view){if(name!=='Leads')return referralPriorList(name);const query=listQuery;let rows;listQuery='';try{rows=referralPriorList(name)}finally{listQuery=query}return rows.filter(l=>{const p=profile(l.profile),g=referralGiver(l);return (!query||referralFold([p?.name,p?.phone,p?.nik,l.id,l.need,l.branch,l.referral,g.name,g.organization,l.referralExternalCode].join(' ')).includes(referralFold(query)))&&(!referralLeadFilter||referralLead(l)&&g.key===referralLeadFilter)&&(!referralLeadType||referralLead(l)&&g.type===referralLeadType)})};
const referralPriorScale=scaleList;
scaleList=function(){let html=referralPriorScale();if(view!=='Leads')return html;const controls=referralFilter('Pemberi referral','referralGiver',referralOptions().map(g=>[g.key,g.label+' ('+g.count+')']),referralLeadFilter,'referralSetLead(this.value)')+referralFilter('Jenis referral','referralTypeFilter',['Internal','Eksternal','Belum ditetapkan'],referralLeadType,'referralSetLead(this.value,true)');html=html.replace('<div class="filterline">','<div class="filterline">'+controls).replace('Cari nama, kebutuhan, atau ID…','Cari Lead, kebutuhan, atau nama pemberi referral…');if(referralLeadFilter||referralLeadType)html=html.replace('<div class="listhead">','<p class="hint">Filter referral mengikuti chip tahap yang dipilih. Pilih Semua untuk melihat hasil konversi juga.</p><div class="listhead">');return html};
const referralPriorReset=resetLists;
