const referralPriorDetail=leadRecordDetail;
leadRecordDetail=function(l){if(recordTab!=='Referral')return referralPriorDetail(l);const box=document.createElement('div');box.innerHTML=referralPriorDetail(l);for(const section of box.querySelectorAll('section'))if(!section.classList.contains('recordhero'))section.remove();return box.innerHTML+referralDetail(l)};
function referralReportRows(){return visible(db.leads).filter(referralLead).filter(l=>{const g=referralGiver(l),query=referralFold([g.name,l.referral,g.organization,pname(l.profile),l.id,l.owner,l.referralExternalCode].join(' '));return (!month||referralDate(l).startsWith(month))&&(!referralReportGiver||g.key===referralReportGiver)&&(!referralReportType||g.type===referralReportType)&&(!referralReportProduct||(referralReportProduct==='__unknown__'?!l.referredProduct:l.referredProduct===referralReportProduct))&&(!referralReportOwner||l.owner===referralReportOwner)&&(!referralReportQuery||query.includes(referralFold(referralReportQuery)))})}
function referralReportGroups(rows){const map=new Map();for(const l of rows){const g=referralGiver(l),c=referralContext(l),r=map.get(g.key)||{...g,total:0,withOpp:0,newCustomers:0,withWon:0,won:0,lost:0,cancelled:0,active:0,known:true};if(r.organization!==g.organization)r.organization='Beberapa cabang / organisasi';r.total++;if(c.metrics.total)r.withOpp++;if(c.newCustomer)r.newCustomers++;if(c.metrics.won)r.withWon++;for(const k of ['won','lost','cancelled','active'])r[k]+=c.metrics[k]||0;r.known=r.known&&c.metrics.known;map.set(g.key,r)}return [...map.values()].sort((a,b)=>b.total-a.total||a.name.localeCompare(b.name))}
