function referralReport(){const rows=referralReportRows(),groups=referralReportGroups(rows),all=visible(db.leads).filter(referralLead),products=[...new Set(all.map(l=>l.referredProduct).filter(Boolean))].sort(),owners=[...new Set(all.map(l=>l.owner))].sort();const pages=Math.max(1,Math.ceil(groups.length/10));referralReportPage=Math.max(1,Math.min(referralReportPage,pages));const c=rows.map(referralContext),metrics=[['Referral diterima',rows.length],['Lead dengan Opportunity',c.filter(x=>x.metrics.total).length],['Konversi Customer baru',c.filter(x=>x.newCustomer).length],['Lead dengan Won',c.some(x=>!x.metrics.known)?'Belum lengkap':c.filter(x=>x.metrics.won).length]];return '<section class="panel ref-report"><div class="ref-heading"><div><small>EFEKTIVITAS REFERRAL</small><h2>Hasil per pemberi referral</h2><p>Periode mengikuti tanggal referral diterima; data lama memakai tanggal Lead. Konversi dan hasil bisnis menunjukkan posisi saat ini, sesuai hak akses Anda.</p></div>'+btn('Export referral CSV','exportReferralReport()')+'</div><div class="ref-report-filters"><label class="ref-filter"><span>Cari referral</span><input aria-label="Cari referral pada laporan" placeholder="Nama pemberi, calon pelanggan, AO atau kode" value="'+E(referralReportQuery)+'" onchange="referralReportSet(\'query\',this.value)"></label>'+referralFilter('Pemberi referral laporan','reportGiver',referralOptions().map(g=>[g.key,g.label]),referralReportGiver,'referralReportSet(\'giver\',this.value)')+referralFilter('Jenis referral laporan','reportType',['Internal','Eksternal','Belum ditetapkan'],referralReportType,'referralReportSet(\'type\',this.value)')+referralFilter('Produk referral awal','reportProduct',[...products,['__unknown__','Produk awal belum tercatat']],referralReportProduct,'referralReportSet(\'product\',this.value)')+referralFilter('AO penanggung jawab referral','reportOwner',owners,referralReportOwner,'referralReportSet(\'owner\',this.value)')+btn('Reset filter referral','referralReportReset()')+'</div><div class="ref-report-metrics">'+metrics.map(([k,v])=>'<div><small>'+k+'</small><strong>'+v+'</strong></div>').join('')+'</div><div class="scrolltable"><table class="datatable"><thead><tr><th>Pemberi referral</th><th>Referral</th><th>Ada Opportunity</th><th>Customer baru</th><th>Opp aktif</th><th>Opp Won / Lost / Cancelled</th><th>Konversi ke Opp</th><th></th></tr></thead><tbody>'+groups.slice((referralReportPage-1)*10,referralReportPage*10).map(g=>'<tr><td><strong>'+E(g.name)+'</strong><small>'+E(g.type)+' · '+E(g.organization||'Organisasi belum dicatat')+'</small></td><td>'+g.total+'</td><td>'+g.withOpp+'</td><td>'+g.newCustomers+'</td><td>'+(g.known?g.active:'Belum lengkap')+'</td><td>'+(g.known?g.won+' / '+g.lost+' / '+g.cancelled:'Belum lengkap')+'</td><td>'+Math.round(100*g.withOpp/Math.max(1,g.total))+'%</td><td>'+btn('Lihat Leads',leadCall('referralDrill',g.key))+'</td></tr>').join('')+'</tbody></table></div>'+(!groups.length?empty('Tidak ada referral sesuai filter.'): '')+'<div class="pagination"><span>'+groups.length+' pemberi referral</span><div>'+btn('‹','referralReportPage=Math.max(1,referralReportPage-1);renderContent()').replace('<button','<button '+(referralReportPage<=1?'disabled':''))+'<b>'+referralReportPage+' / '+pages+'</b>'+btn('›','referralReportPage++;renderContent()').replace('<button','<button '+(referralReportPage>=pages?'disabled':''))+'</div></div><p class="hint">Konversi ke Opportunity = jumlah Lead referral yang memiliki Opportunity ÷ jumlah Lead referral. Customer existing tidak dihitung sebagai Customer baru. Jumlah Won / Lost / Cancelled menghitung Opportunity, sehingga satu referral bisa menghasilkan beberapa Opportunity. Data lama tanpa produk awal tetap ditandai belum tercatat.</p></section>'}
