function exportReferralReport(){downloadCsv('efektivitas-referral',[['Lead ID','Calon pelanggan','Pemberi referral','Jenis','Organisasi','Kode eksternal','Tanggal diterima (WITA)','Produk awal referral','Produk Lead saat ini','AO','Cabang penanganan','Status penanganan','Opportunity tertaut','Opp aktif','Opp Won','Opp Lost','Opp Cancelled','Konversi Customer baru','Customer existing','Aktivitas terakhir','Hasil follow-up terakhir','Task berikutnya','Jadwal Task berikutnya'],...referralReportRows().map(l=>{const g=referralGiver(l),c=referralContext(l),a=c.activities[0],t=c.open[0];return [l.id,pname(l.profile),g.name,g.type,g.organization,l.referralExternalCode,referralDate(l),l.referredProduct||'Belum tercatat',l.product,l.owner,l.branch,referralHandling(l),c.metrics.total,c.metrics.known?c.metrics.active:'Belum lengkap',c.metrics.known?c.metrics.won:'Belum lengkap',c.metrics.known?c.metrics.lost:'Belum lengkap',c.metrics.known?c.metrics.cancelled:'Belum lengkap',c.newCustomer?'Ya':'Tidak',c.existingCustomer?'Ya':'Tidak',a?.occurred||a?.recorded||'',a?.note||'',t?.purpose||'',t?.scheduled||'']})])}

